     * Так выглядит результат полностраничного OCR: текст всего листа лежит
     * в одной рамке (0,0,1,1). Такой регион нельзя использовать как цель
     * для тапа — иначе касание ЛЮБОЙ точки страницы, включая пустые поля,
     * открывает панель распознанного текста.
     */
    val isWholePage: Boolean
        get() = boundingBox.left <= 0.001f &&
            boundingBox.top <= 0.001f &&
            boundingBox.right >= 0.999f &&
            boundingBox.bottom >= 0.999f
}

data class OcrPageResult(
    val chapterId: Long,
    val pageIndex: Int,
    val ocrModel: OcrModel,
    val imageWidth: Int,
    val imageHeight: Int,
    val regions: List<OcrRegion>,
) {
    val text: String
        get() = regions.joinToString(separator = " ") { flattenOcrTextForQuery(it.text) }.trim()
}

fun flattenOcrTextForQuery(text: String): String {
    if (text.isBlank()) return text.trim()
    return text
        .replace(Regex("\\s+"), " ")
        .trim()
}

fun normalizeOcrTextForDisplay(text: String): String {
    if (text.isEmpty()) return text

    return text
        .replace(Regex("[ ]*[.．・･…]{2,}")) { match ->
            dotRunToEllipses(match.value.trimStart(' '))
        }
        .replace(Regex("[!！]{2,}"), "‼")
        .replace(Regex("[?？]{2,}"), "⁇")
        .replace(Regex("[!！][?？]+"), "⁉")
        .replace(Regex("[?？][!！]+"), "⁈")
}

private fun dotRunToEllipses(dotRun: String): String {
    val dotCount = dotRun.sumOf {
        when (it) {
            '…' -> 3
            '.', '．', '・', '･' -> 1
            else -> 0
        }
    }
    val ellipsisCount = dotCount / 3
    val remainder = dotCount % 3

    return buildString(ellipsisCount + if (remainder >= 2) 1 else remainder) {
        repeat(ellipsisCount) { append('…') }
        when (remainder) {
            1 -> append('.')
            2 -> append('…')
        }
    }
}

